    id: "bus-2025-ol-s2-q7e", topicId: "business-3-18", conceptId: "net-pay-calculation",
    section: "2", questionRef: "2025 OL Section 2 Q7(E)",
    stem: "Managing. David Mulroy was successful in his application to work as a Staff Industrial Engineer at Dexcom. The following is a breakdown of his earnings: Annual Gross Pay €46,000. PAYE 20% on the first €42,000 and 40% on the remainder. Annual Tax Credit €3,750. PRSI 4.1%. USC 3.0%.",
    questionText: "Calculate David’s Annual Net Salary. Show your workings.",
    tariffModel: {"kind":"fixed","notation":"15m (1 + 2 + 2 + 2 + 2 + 2 + 2 + 2)","answer":null,"ofParts":null,"perPart":null}, totalMarks: 15,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Gross Pay 46,000", marks: 1, contextNote: "One mark for opening the workings with the gross figure the table gives." },
    { id: "r-2", kind: "point", verbatim: "PAYE : 20% @ 42,000 8,400 40% @ 4,000 +1,600 Gross PAYE 10,000", marks: 4, contextNote: "Two marks for the standard-rate band and two for the higher rate. The 40% is charged on the €4,000 above €42,000, not on the whole €46,000 — the two bands are added to give gross PAYE of €10,000." },
    { id: "r-3", kind: "point", verbatim: "Less Tax Credit 3,750 -3,750 Net PAYE 6,250", marks: 2, contextNote: "Two marks for taking the tax credit off the tax due. The credit comes off the gross PAYE, not off the gross pay, which leaves net PAYE of €6,250." },
    { id: "r-4", kind: "point", verbatim: "PRSI: 46,000@4.1% 1,886 USC 46,000@3.0% 1,380", marks: 4, contextNote: "Two marks for PRSI and two for USC. Both are charged on the full gross pay of €46,000 — the tax credit does not reduce either of them." },
    { id: "r-5", kind: "point", verbatim: "Total Annual Deductions 9,516 Net Annual Salary 36,484", marks: 4, contextNote: "Two marks for the total deductions and two for the net figure. Total deductions are net PAYE plus PRSI plus USC (6,250 + 1,886 + 1,380), taken off the €46,000 gross." },
    ],
